'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roleLabel=r=>({master:'Master',coordenador:'Coordenador',especial:'Especial',aluno:'Aluno',user:'Aluno'}[r]||r);
const manages=()=>['master','coordenador'].includes(ME?.role);
const days=['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'];
const names={planned:'Aguardando registro',done:'Concluído',partial:'Parcial',missed:'Não realizado',fixed:'Compromisso',review:'Revisão',study:'Estudo',action:'Ação pessoal'};
let ME,CSRF='',S=null,P=null,accounts=[],target='',view='home',week='',calendar=[],mode=innerWidth<760?'list':'grid',dirty=false,saving=false,modalHandler=null,timer;
const date=s=>new Date(s+'T12:00:00');
const iso=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const add=(s,n)=>{let d=date(s);d.setDate(d.getDate()+n);return iso(d);};
const weekOf=s=>add(s,-date(s).getDay());/*v3718*/
const br=s=>s?date(s).toLocaleDateString('pt-BR'):'—';
const hm=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
const minutes=n=>n>=60?Math.floor(n/60)+'h'+(n%60?' '+Math.round(n%60)+'min':''):Math.round(n)+'min';
const button=(text,act,cls='secondary',attrs='')=>`<button class="${cls}" data-act="${act}" ${attrs}>${text}</button>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const input=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" value="${esc(value)}" type="${type}" ${attrs}></label>`;
const area=(label,name,value='',hint='')=>`<label>${label}<textarea name="${name}" maxlength="20000">${esc(value)}</textarea>${hint?'<small>'+hint+'</small>':''}</label>`;
const select=(label,name,value,options)=>`<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const check=(label,name,value=false)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const head=(title,desc,actions='')=>`<div class="page-head"><div><p class="eyebrow">MEU CRONOGRAMA</p><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const empty=text=>`<div class="empty">${text}</div>`;
const sub=id=>P?.subjects.find(x=>x.id===id)?.name||'Sem disciplina';
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.hidden=false;t.setAttribute('role',error?'alert':'status');clearTimeout(timer);timer=setTimeout(()=>t.hidden=true,7500);}
function status(text,error=false){$('#save-status').textContent=text;$('#save-status').className=error?'form-error':'';}
function safeLeave(){return !dirty||confirm('Há alterações não salvas. Deseja sair e descartá-las?');}
async function api(url,data){
 const r=await fetch(url,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:data===undefined?undefined:JSON.stringify(data)});
 const result=await r.json().catch(()=>({error:'Resposta inesperada do servidor.'}));
 if(!r.ok){if(r.status===401){status('Sessão expirada · entre novamente',true);throw new Error('Sessão expirada. Suas alterações não foram salvas. Reabra o site e entre novamente.');}if(r.status===409)status('Conflito de versão · atualize antes de salvar',true);throw new Error(result.error||'Não foi possível concluir.');}return result;
}
async function load(){S=await api('/api/state?user='+encodeURIComponent(target));P=S.profile;CSRF=S.csrf;dirty=false;status('Salvo no servidor · versão '+S.version);if(!week)week=weekOf(S.serverDate);await loadCalendar();render();}
async function loadCalendar(){if(!P)return;calendar=(await api('/api/calendar?user='+encodeURIComponent(target)+'&week='+week)).fixed;}
async function save(op,data){if(saving)throw new Error('Uma gravação já está em andamento.');saving=true;status('Salvando no servidor…');try{const result=await api('/api/action',{user:target,version:S.version,op,data});S=result;P=result.profile;dirty=false;status('Salvo no servidor · versão '+S.version);try{await loadCalendar();}catch(_){toast('Salvo, mas o quadro não pôde ser recarregado. Atualize a página quando a conexão voltar.',true);}render();toast('Alterações salvas no servidor.');return result;}catch(e){status('Não salvo · mantenha esta tela aberta',true);throw e;}finally{saving=false;}}
function modal(title,body,handler){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;modalHandler=handler;$('#dialog').showModal();}
function closeModal(force=false){if(!force&&dirty&&!confirm('Descartar as alterações deste formulário?'))return;$('#dialog').close();$('#dialog-body').innerHTML='';modalHandler=null;dirty=false;}
function fd(f){return Object.fromEntries(new FormData(f).entries());}
function modalForm(title,body,handler,submit='Salvar'){modal(title,`<form id="modal-form">${body}<p id="modal-error" class="form-error" role="alert"></p><div class="actions"><button class="primary" type="submit">${submit}</button></div></form>`,handler);}
function items(rows){return rows.length?rows.join(''):empty('Nenhum registro por enquanto.');}
const navItems=[['home','Visão geral'],['mapping','Mapeamento objetivo'],['diagnosis','Observações pessoais'],['routine','Rotina e horários'],['subjects','Disciplinas e metas'],['contents','Conteúdos estudados'],['calendar','Quadro semanal'],['reviews','Minhas revisões'],['review-table','Tabela de revisões'],['checks','Verificações'],['result-model','Modelo de resultados'],['result-import','Importar resultados'],['performance','Desempenho'],['reports','Meus relatórios'],['report-admin','Cadastro de relatórios'],['result-export','Exportar resultados'],['exams','Mapa de questões'],['data','Dados e backup'],['password','Minha senha']];
function renderNav(){const entries=[...navItems.filter(x=>!['exams','result-model','result-export','result-import','report-admin'].includes(x[0])||manages()),...(manages()?[['accounts',ME.role==='master'?'Painel Master':'Meus alunos']]:[])];$('#nav').innerHTML=entries.map(([id,label],i)=>`<button data-view="${id}" class="${view===id?'active':''}"><span class="nav-number">${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('');}
function render(){
 renderNav();$('#user-label').textContent=ME.name+' · '+roleLabel(ME.role);
 $('#master-note').hidden=!(manages()&&target!==ME.id);$('#master-note').textContent=P?'Você está editando a conta de '+P.name+'. As alterações serão salvas na conta dela.':'';
 if(ME.must_change){view='password';$('#main').innerHTML=passwordView(true);return;}
 const pages={home:homeView,diagnosis:diagnosisView,routine:routineView,subjects:subjectsView,contents:contentsView,calendar:calendarView,reviews:reviewsView,checks:checksView,data:dataView,password:()=>passwordView(false),accounts:accountsView,performance:performanceView,reports:reportsView,'report-admin':reportAdminView,mapping:mappingView,exams:examsView,'result-model':resultModelView,'result-import':resultImportView,'result-export':resultExportView};$('#main').innerHTML=(pages[view]||homeView)();
}
function homeView(){
 const current=weekOf(S.serverDate),sessions=P.sessions.filter(x=>x.date>=current&&x.date<=add(current,6)),planned=sessions.filter(x=>x.status!=='missed').reduce((n,x)=>n+x.end-x.start,0),done=P.feedback.filter(x=>x.date>=current&&x.date<=add(current,6)).reduce((n,x)=>n+x.actualMin,0),due=P.contents.filter(x=>x.status==='studied'&&!x.paused&&x.nextDue<=S.serverDate),pending=sessions.filter(x=>x.status==='planned');
 return head('Sua rotina, com direção.','Organize o que cabe na semana. Registre o que aconteceu. Ajuste com base em evidências.')+`<div class="card hero"><p class="eyebrow">${esc(P.name)}</p><h2>${P.answers.goal?esc(P.answers.goal):'Comece conhecendo sua disponibilidade.'}</h2><p>${P.availability.every(x=>x.status==='unknown')?'Preencha o mapeamento objetivo e confirme seus horários. Tempo não informado não é considerado livre.':'As revisões entram dentro da sua capacidade semanal, sem preencher automaticamente todo espaço vazio.'}</p><div class="actions">${button('Abrir meu quadro','go-calendar','primary')}${button('Registrar conteúdo','new-content')}</div></div><div class="stats"><div class="stat"><strong>${minutes(planned)}</strong><span>planejadas nesta semana</span></div><div class="stat"><strong>${minutes(done)}</strong><span>de execução registrada</span></div><div class="stat"><strong>${due.length}</strong><span>conteúdos com revisão vencendo ou atrasada</span></div><div class="stat"><strong>${pending.length}</strong><span>blocos sem resultado informado</span></div></div><div class="columns"><section class="card"><h2>Próximas ações</h2>${items(P.sessions.filter(x=>x.status==='planned'&&x.date>=S.serverDate).slice(0,6).map(sessionItem))}</section><section class="card"><h2>Orientação de hoje</h2><p>Na revisão, tente explicar o conteúdo ou resolver uma questão sem consulta. Depois confira, corrija e registre se precisou de ajuda.</p><div class="notice">Não realizar uma atividade é diferente de não compreender o conteúdo. O sistema registra as duas situações separadamente.</div><h3>Pendências de encaixe</h3>${items(P.pending.slice(0,5).map(x=>`<div class="item"><div class="item-main"><strong>${esc(x.title)}</strong><p>${esc(x.reason)}</p></div>${tag(minutes(x.minutes||0),'warning')}</div>`))}</section></div>`;
}
function diagnosisView(){const a=P.answers;return head('Observações pessoais','As respostas abertas ficam para consulta. Preferências, disponibilidade e resultados estruturados orientam os cálculos.')+`<form id="diagnosis-form" class="card"><div class="form-grid">${area('O que você deseja alcançar?','goal',a.goal)}${area('Como é sua rotina atual?','context',a.context)}${input('Prazo principal, quando houver','deadline',a.deadline,'date')}${select('Em qual período você costuma render melhor?','energy',a.energy,[['manha','Manhã'],['tarde','Tarde'],['noite','Noite'],['qualquer','Sem preferência']])}${area('Responsabilidades e atividades que não podem faltar','responsibilities',a.responsibilities)}${area('O que costuma dificultar começar?','startDifficulty',a.startDifficulty)}${input('Quanto tempo costuma manter o foco?','focus',a.focus,'text','maxlength="200"')}${area('Onde você estuda e quais são as interrupções?','environment',a.environment)}${area('Quem pode ajudar quando houver dificuldade?','support',a.support)}${area('O que ajuda a retomar depois de um dia difícil?','recovery',a.recovery)}${area('Outras observações','notes',a.notes)}</div><h3>Obstáculos que você reconhece</h3><div class="check-list">${['tempo','cansaço','distração','dificuldade de conteúdo','tarefas pouco claras','imprevistos'].map(x=>check(esc(x),'obstacle:'+x,a.obstacles.includes(x))).join('')}</div><div class="notice">Descreva somente informações necessárias ao planejamento. O Master tem acesso aos dados desta conta. Este formulário não faz diagnóstico de saúde.</div><button type="submit" class="primary">Salvar diagnóstico</button></form>`;}
function routineView(){const s=P.settings;return head('Rotina e horários','Confirme o tempo realmente livre e cadastre compromissos. Deslocamentos, pausas, sono e imprevistos serão respeitados.')+`<form id="routine-form" class="card"><h2>Disponibilidade confirmada</h2><p class="muted">Faixas no formato 14:00-16:00; 19:00-21:00. Uma faixa por período, no mesmo dia.</p>${P.availability.map((x,i)=>`<div class="day-row"><strong>${days[i]}</strong>${select('Situação','status'+i,x.status,[['unknown','Não informado'],['available','Disponível'],['unavailable','Indisponível']])}${input('Faixas livres','range'+i,x.ranges.map(r=>r.start+'-'+r.end).join('; '),'text','placeholder="14:00-16:00; 19:00-21:00"')}</div>`).join('')}<h2>Limites do planejamento</h2><div class="form-grid">${input('Início do sono','sleepStart',s.sleepStart,'time','required')}${input('Fim do sono','sleepEnd',s.sleepEnd,'time','required')}${input('Bloco mínimo (min)','sessionMin',s.sessionMin,'number','min="10" max="120" required')}${input('Bloco máximo (min)','sessionMax',s.sessionMax,'number','min="10" max="180" required')}${input('Pausa entre blocos (min)','breakMin',s.breakMin,'number','min="0" max="60" required')}${input('Limite diário (min)','dailyMax',s.dailyMax,'number','min="10" max="720" required')}${input('Limite semanal (min)','weeklyGoal',s.weeklyGoal,'number','min="10" max="5040" required')}${input('Reserva para imprevistos (%)','reservePct',s.reservePct,'number','min="0" max="80" required')}${input('Revisão padrão (min)','reviewMin',s.reviewMin,'number','min="10" max="180" required')}${input('Intervalos de revisão (dias)','intervals',s.intervals.join(', '),'text','required')}${select('Preferência de horário','preferred',s.preferred,[['manha','Manhã'],['tarde','Tarde'],['noite','Noite'],['qualquer','Sem preferência']])}${check('Permitir primeira revisão no mesmo dia','sameDay',s.sameDay)}</div><p class="micro">Os intervalos são parâmetros configuráveis, não uma sequência universal. A retomada no mesmo dia preserva pelo menos duas horas desde o início do estudo e ocorre depois do seu término.</p><button type="submit" class="primary">Salvar rotina e limites</button></form><section class="card"><div class="page-head"><h2>Compromissos fixos</h2>${button('Adicionar compromisso','new-fixed','primary')}</div>${items(P.fixed.map(x=>`<div class="item"><div class="item-main"><strong>${esc(x.title)}</strong><p>${esc(x.start)}–${esc(x.end)} · ${{weekly:'Semanal',biweekly:'Quinzenal',once:'Uma data'}[x.recurrence]} · ${x.days.map(d=>days[d]).join(', ')}</p><small>Início: ${br(x.anchor)} · deslocamentos: ${x.before+x.after} min</small></div><div class="item-actions">${button('Editar','edit-fixed','secondary',`data-id="${x.id}"`)}${button('Excluir','delete','danger-button',`data-collection="fixed" data-id="${x.id}"`)}</div></div>`))}</section><section class="card"><div class="page-head"><h2>Bloqueios em datas específicas</h2>${button('Adicionar bloqueio','new-exception')}</div>${items(P.exceptions.map(x=>`<div class="item"><div><strong>${esc(x.title)}</strong><p>${br(x.date)} · ${esc(x.start)}–${esc(x.end)}</p></div>${button('Excluir','delete','danger-button',`data-collection="exceptions" data-id="${x.id}"`)}</div>`))}</section>`;}
function subjectForm(id){const x=P.subjects.find(x=>x.id===id)||{name:'',kind:'study',action:'Estudar e praticar',weeklyMin:120,difficulty:3,importance:3,examDate:'',active:true};modalForm(id?'Editar disciplina ou ação':'Nova disciplina ou ação',`<div class="form-grid">${input('Nome','name',x.name,'text','required maxlength="150"')}${select('Tipo','kind',x.kind,[['study','Disciplina / estudo'],['personal','Ação pessoal']])}${input('Ação exibida no quadro','action',x.action,'text','maxlength="300"')}${input('Meta semanal (min)','weeklyMin',x.weeklyMin,'number','min="0" max="3000" required')}${select('Dificuldade percebida','difficulty',x.difficulty,[1,2,3,4,5].map(n=>[n,n+' / 5']))}${select('Importância','importance',x.importance,[1,2,3,4,5].map(n=>[n,n+' / 5']))}${input('Data de avaliação ou prazo','examDate',x.examDate,'date')}${check('Meta ativa','active',x.active)}</div>`,async(f,d)=>{await save('subject',{...d,...(id?{id}:{}),weeklyMin:+d.weeklyMin,difficulty:+d.difficulty,importance:+d.importance,active:f.elements.active.checked});});}
function subjectsView(){return head('Disciplinas e metas','Indique prioridades sem confundir dificuldade percebida com desempenho verificado.',button('Adicionar','new-subject','primary'))+`<div class="card">${items(P.subjects.map(x=>`<div class="item"><div class="item-main"><strong>${esc(x.name)} ${tag(x.active?'Ativa':'Pausada',x.active?'done':'')}</strong><p>${minutes(x.weeklyMin)} por semana · dificuldade ${x.difficulty}/5 · importância ${x.importance}/5</p><small>${esc(x.action)}${x.examDate?' · Prazo: '+br(x.examDate):''}</small></div><div class="item-actions">${button('Editar','edit-subject','secondary',`data-id="${x.id}"`)}${button('Excluir','delete','danger-button',`data-collection="subjects" data-id="${x.id}"`)}</div></div>`))}</div><div class="notice">Ao haver acertos independentes em pelo menos dois dias e seis questões, o motor passa a considerar também o desempenho registrado para redistribuir o tempo. A carga total continua limitada pela rotina.</div>`;}
function contentForm(){if(!P.subjects.length){toast('Cadastre primeiro uma disciplina.');view='subjects';render();return;}modalForm('Registrar conteúdo',`<div class="form-grid">${select('Disciplina','subjectId','',P.subjects.filter(x=>x.active).map(x=>[x.id,x.name]))}${input('Conteúdo','title','','text','required maxlength="300"')}${input('Tópico geral','topic','','text','maxlength="300"')}${select('Situação','status','studied',[['studied','Já estudei'],['planned','Pretendo estudar']])}${input('Data','studiedOn',S.serverDate,'date','required')}${input('Horário de início','studiedTime','09:00','time','required')}${input('Tempo de estudo (min)','studyMinutes',40,'number','min="0" max="720" required')}${input('Duração da revisão (min)','reviewMinutes',P.settings.reviewMin,'number','min="10" max="180" required')}${select('Dificuldade percebida','difficulty',3,[1,2,3,4,5].map(n=>[n,n+' / 5']))}${input('Material, páginas ou referência','material','','text','maxlength="5000"')}${area('Observações','notes','')}</div><p class="micro">Conteúdos futuros só recebem revisão depois de o estudo ser confirmado. Materiais são referências em texto, sem upload de anexos.</p>`,async(f,d)=>save('content',{...d,studyMinutes:+d.studyMinutes,reviewMinutes:+d.reviewMinutes,difficulty:+d.difficulty}));}
function contentsView(){return head('Conteúdos estudados','Acrescente os conteúdos conforme as aulas e os estudos acontecerem.',button('Registrar conteúdo','new-content','primary'))+`<input class="search-input" id="content-search" placeholder="Filtrar por disciplina, tópico ou conteúdo" aria-label="Filtrar conteúdos"><div class="card" id="content-list">${contentRows(P.contents)}</div>`;}
function contentRows(contents){return items(contents.slice().reverse().map(c=>`<div class="item"><div class="item-main"><strong>${esc(c.title)}</strong><p>${esc(sub(c.subjectId))}${c.topic?' → '+esc(c.topic):''}</p><small>${c.status==='studied'?'Estudado em '+br(c.studiedOn):'Planejado para '+br(c.studiedOn)} · ${c.paused?'Revisão pausada':c.nextDue?'Próxima revisão: '+br(c.nextDue):'Revisão ainda não habilitada'}</small>${c.material?'<p>Material: '+esc(c.material)+'</p>':''}${c.notes?'<p>'+esc(c.notes)+'</p>':''}</div><div class="item-actions">${button(c.status==='planned'?'Confirmar estudo':'Novo encontro','restudy','secondary',`data-id="${c.id}"`)}${button('Revisão','edit-review','secondary',`data-id="${c.id}"`)}${button('Excluir','delete','danger-button',`data-id="${c.id}" data-collection="contents"`)}</div></div>`));}
function sessionItem(x){return `<div class="item ${x.kind==='fixed'?'fixed-row':''}"><div class="time">${hm(x.start)}–${hm(x.end)}<small>${br(x.date)}</small></div><div class="item-main"><strong>${esc(x.title)}</strong><p>${tag(names[x.kind]||x.kind,x.kind)} ${tag(names[x.status],x.status)} ${x.locked?tag('Fixado'):''}</p>${x.reason?'<small>'+esc(x.reason)+'</small>':''}</div>${x.kind!=='fixed'&&x.status==='planned'?`<div class="item-actions">${button('Registrar resultado','feedback','primary',`data-id="${x.id}"`)}${button('Ajustar horário','edit-session','secondary',`data-id="${x.id}"`)}${button('Remover','delete','danger-button',`data-id="${x.id}" data-collection="sessions"`)}</div>`:''}</div>`;}
function calendarView(){const all=[...calendar,...P.sessions.filter(x=>x.date>=week&&x.date<=add(week,6))].sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start);const controls=`<div class="actions"><label>Semana de<input id="week-input" type="date" value="${week}"></label>${button('Gerar / recalcular','generate','primary')}${button(mode==='list'?'Ver grade':'Ver lista','calendar-mode')}${button('Imprimir','print')}</div>`;let body;
 if(mode==='list')body=Array.from({length:7},(_,i)=>{let d=add(week,i);return `<section class="card agenda-day"><h3>${days[(i+6)%7]} <small>${br(d)}</small></h3>${items(all.filter(x=>x.date===d).map(sessionItem))}</section>`;}).join('');
 else{let grid='<div class="cell grid-head">Hora</div>'+Array.from({length:7},(_,i)=>`<div class="cell grid-head">${days[(i+6)%7]}<br>${br(add(week,i))}</div>`).join('');for(let h=0;h<24;h++){if(h<6&&!all.some(x=>x.start<h*60+60&&x.end>h*60))continue;grid+=`<div class="cell">${hm(h*60)}</div>`;for(let i=0;i<7;i++){let d=add(week,i);grid+='<div class="cell">'+all.filter(x=>x.date===d&&x.start<(h+1)*60&&x.end>h*60).map(x=>x.kind==='fixed'?`<div class="grid-event fixed">${hm(x.start)}–${hm(x.end)}<br>${esc(x.title)}</div>`:`<button class="grid-event ${x.status==='done'?'done':x.kind}" data-act="session-detail" data-id="${x.id}">${hm(x.start)}–${hm(x.end)}<br>${esc(x.title)}<br>${esc(names[x.status])}</button>`).join('')+'</div>';}}body=`<div class="card table-wrap"><div class="week-grid">${grid}</div></div>`;}
 return head('Quadro semanal','O recálculo preserva resultados, blocos passados e horários fixados. Compromissos existentes também aparecem no quadro.')+`<div class="card">${controls}${P.planMeta?.dirty?'<p class="form-error">A rotina mudou desde o último cálculo. Recalcule a semana quando terminar as alterações.</p>':''}</div>`+body+`<div class="card"><h2>Pendências e limites</h2>${items(P.pending.map(x=>`<div class="item"><div><strong>${esc(x.title)}</strong><p>${esc(x.reason)}</p></div>${tag(minutes(x.minutes||0),'warning')}</div>`))}<p class="micro">O motor usa uma heurística de encaixe. Uma pendência não prova impossibilidade matemática e o resultado não é necessariamente a melhor combinação global.</p></div>`;}
function reviewsView(){const contents=P.contents.filter(x=>x.status==='studied').sort((a,b)=>(a.nextDue||'').localeCompare(b.nextDue||''));return head('Minhas revisões','Revisões periódicas com registro de questões, monitoria, método utilizado e percepção de dificuldade.')+`<div class="card">${items(contents.map(c=>`<div class="item"><div class="item-main"><strong>${esc(c.title)}</strong><p>${esc(sub(c.subjectId))} · ${minutes(c.reviewMinutes)} · ${c.paused?'Pausada':'Data-alvo: '+br(c.nextDue)}</p>${tag(c.paused?'Pausada':c.nextDue<=S.serverDate?'Revisar / verificar pendência':'Programada',c.nextDue<=S.serverDate&&!c.paused?'warning':'')}<small>Etapa ${c.stage+1} · intervalo atual: ${P.settings.intervals[c.stage]} dia(s)</small></div><div class="item-actions">${button('Registrar revisão','feedback-content','primary',`data-id="${c.id}"`)}${button('Ajustar / pausar','edit-review','secondary',`data-id="${c.id}"`)}</div></div>`))}</div>`;}
function checksView(){return head('Verificações','Tempo de execução, domínio e dificuldade são registrados separadamente.')+`<div class="card">${items(P.feedback.map(f=>`<div class="item"><div class="item-main"><strong>${br(f.date)} · ${esc(sub(f.subjectId))}</strong><p>${tag(names[f.status],f.status)} ${minutes(f.actualMin)} · ${f.total?f.correct+'/'+f.total+' acertos':'Sem questões informadas'} · ${{none:'Sem ajuda',some:'Alguma ajuda',full:'Com consulta/ajuda completa'}[f.help]}</p><p>${esc(f.message||'Resultado registrado.')}</p>${f.perceivedDifficulty?'<p>Dificuldade percebida: '+esc({1:'Muito fácil',2:'Fácil',3:'Moderada',4:'Difícil',5:'Muito difícil'}[f.perceivedDifficulty]||f.perceivedDifficulty)+(f.needsAttention?' · Precisa de mais atenção':'')+(f.monitoring?' · Fez monitoria':'')+'</p>':''}${f.reviewDescription?'<small>Como revisou: '+esc(f.reviewDescription)+'</small>':''}${f.advice?'<div class="notice">'+esc(f.advice)+'</div>':''}${f.notes?'<small>'+esc(f.notes)+'</small>':''}</div></div>`))}</div>`;}
function dataView(){return head('Dados e backup','Os registros são salvos na conta online depois da confirmação. Mantenha também uma cópia externa.')+`<div class="columns"><section class="card"><h2>Exportar</h2><p>O JSON restaura o planejamento. Os arquivos CSV podem ser abertos no Excel.</p><div class="actions">${button('Backup desta conta — JSON','export-json','primary')}${ME.role==='master'?button('Backup de todas as contas','export-all'):''}${button('Respostas e rotina — CSV','export-answers')}${button('Verificações — CSV','export-checks')}${button('Semana — CSV','export-week')}${button('Calendário — ICS','export-ics')}</div></section><section class="card"><h2>Importar do RITMO ou deste site</h2><p>A importação substitui o planejamento da conta selecionada, mas não muda login, senha ou permissões. Exporte um backup antes.</p>${button('Selecionar backup JSON','import','secondary')}<p class="micro">Arquivos de até 5 MB. Se houver vários perfis, você escolhe qual importar.</p></section></div><section class="card"><h2>Uso no iPhone</h2><p>Abra sempre o endereço do site no Safari. A sessão e os dados pertencem à conta; não é necessário baixar um HTML.</p><p>O aplicativo precisa de conexão para salvar e carregar. Não há notificações com o site fechado, leitura automática de texto livre ou sincronização offline nesta versão.</p><div class="notice warning">O Master pode visualizar e editar sua rotina. Coordenadores acessam somente contas de alunos; contas especiais são restritas ao titular e ao Master. Backups JSON e CSV não são criptografados. Compartilhe apenas com quem deve receber essas informações.</div>${ME.role==='master'&&ME.databaseExpiration?'<div class="notice danger"><strong>Banco de teste com vencimento</strong><p>Vencimento informado pelo Render: '+esc(new Date(ME.databaseExpiration).toLocaleString('pt-BR'))+'. Faça migração ou upgrade antes dessa data. O serviço gratuito não substitui uma política de backup.</p></div>':''}</section><section class="card"><h2>Histórico das decisões</h2>${items(P.audit.slice(0,60).map(a=>`<div class="item"><div><strong>${esc(a.type)}</strong><p>${esc(a.message)}</p><small>${esc(new Date(a.at).toLocaleString('pt-BR'))}</small></div></div>`))}</section>`;}
function passwordView(required){return head('Minha senha',required?'Troque a senha provisória para continuar.':'Ao trocar a senha, as outras sessões desta conta serão encerradas.')+`<form class="card" id="password-form"><div class="form-grid">${input('Senha atual','current','','password','required autocomplete="current-password" maxlength="128"')}${input('Nova senha','password','','password','required minlength="8" maxlength="128" autocomplete="new-password"')}${input('Confirme a nova senha','confirm','','password','required minlength="8" maxlength="128" autocomplete="new-password"')}</div><p class="micro">Use pelo menos 8 caracteres. Não reutilize a senha de outros serviços.</p><button class="primary" type="submit">Alterar senha</button></form>`;}
function accountsView(){if(ME.role==='coordenador')return coordinatorView();return head('Painel Master','Gerencie contas, acesso e senhas provisórias. A conta arcmb permanece Master.',button('Criar conta','new-account','primary'))+`<div class="card">${items(accounts.map(a=>`<div class="item"><div class="item-main"><strong>${esc(a.name)} ${tag(roleLabel(a.role))}</strong><p>Login: ${esc(a.username)} · ${a.active?'Ativo':'Desativado'} · ${!a.passwordSet?'Senha inicial ainda não definida':a.must_change?'Troca de senha obrigatória':'Senha definida'}</p></div><div class="item-actions">${button('Abrir rotina','open-account','primary',`data-id="${a.id}"`)}${button('Editar acesso','edit-account','secondary',`data-id="${a.id}"`)}</div></div>`))}</div><div class="notice">Para liberar a Mayra: clique em “Editar acesso”, defina uma senha provisória e informe o login <strong>mayra</strong>. Ela deverá trocar essa senha no primeiro acesso.</div><section class="card"><h2>Auditoria de acesso e alterações</h2>${button('Consultar últimos eventos','audit')}<div id="audit-results"></div></section>`;}
function fixedForm(id){let f=P.fixed.find(x=>x.id===id)||{title:'',category:'Pessoal',start:'08:00',end:'09:00',before:0,after:0,recurrence:'weekly',days:[0],anchor:S.serverDate,until:''};modalForm('Compromisso',`<div class="form-grid">${input('Atividade','title',f.title,'text','required maxlength="250"')}${input('Categoria','category',f.category,'text','maxlength="100"')}${input('Início','start',f.start,'time','required')}${input('Término','end',f.end,'time','required')}${input('Deslocamento antes (min)','before',f.before,'number','min="0" max="240"')}${input('Deslocamento depois (min)','after',f.after,'number','min="0" max="240"')}${select('Recorrência','recurrence',f.recurrence,[['weekly','Semanal'],['biweekly','Quinzenal independente'],['once','Somente na data inicial']])}${input('Data inicial / referência da quinzena','anchor',f.anchor,'date','required')}${input('Repetir até (opcional)','until',f.until,'date')}</div><div class="check-list">${days.map((d,i)=>check(d,'day'+i,f.days.includes(i))).join('')}</div><p class="micro">Na recorrência quinzenal, a semana da data inicial é a semana ativa. Cada compromisso mantém seu próprio ciclo. Horário final anterior ao início indica que o compromisso atravessa a meia-noite.</p>`,async(form,d)=>{let list=days.map((_,i)=>i).filter(i=>form.elements['day'+i].checked);if(d.recurrence!=='once'&&!list.length)throw new Error('Selecione pelo menos um dia.');await save('fixed',{id,...d,before:+d.before,after:+d.after,days:list});});}
function feedbackForm(sessionId,contentId){const x=P.sessions.find(x=>x.id===sessionId),c=P.contents.find(c=>c.id===(x?.contentId||contentId));modalForm('Registrar execução e verificação',`<div class="notice"><strong>${esc(x?.title||c?.title)}</strong><p>Tente recuperar o conhecimento sem consulta antes de conferir o material.</p></div><div class="form-grid">${select('Resultado','status','done',[['done','Concluí'],['partial','Fiz parcialmente'],['missed','Não consegui fazer']])}${input('Data da execução','date',S.serverDate,'date',`required max="${S.serverDate}"`)}${input('Tempo utilizado (min)','actualMin',x?x.end-x.start:c?.reviewMinutes||20,'number','min="0" max="720" required')}${input('Questões verificadas','total',0,'number','min="0" max="500" required')}${input('Acertos','correct',0,'number','min="0" max="500" required')}${select('Ajuda ou consulta','help','none',[['none','Resolvi sem ajuda'],['some','Precisei de alguma ajuda'],['full','Precisei consultar / ajuda completa']])}${select('Confiança nas respostas','confidence','medium',[['low','Baixa'],['medium','Média'],['high','Alta']])}${select('Dificuldade percebida','perceivedDifficulty','3',[['1','Muito fácil'],['2','Fácil'],['3','Moderada'],['4','Difícil'],['5','Muito difícil']])}${select('Fez atendimento de monitoria?','monitoring','no',[['no','Não'],['yes','Sim']])}${select('Obstáculo, quando houver','reason','',[['','Nenhum / não informar'],['time','Falta de tempo'],['tired','Cansaço'],['difficulty','Dificuldade de conteúdo'],['distraction','Distração'],['unclear','Tarefa pouco clara'],['unexpected','Imprevisto'],['other','Outro']])}</div><h3>Como você revisou?</h3><div class="check-list"><label><input type="checkbox" name="method_questoes"> Questões</label><label><input type="checkbox" name="method_correcao"> Refiz questões erradas / correção</label><label><input type="checkbox" name="method_resumo"> Resumo ou fichamento</label><label><input type="checkbox" name="method_flashcards"> Flashcards</label><label><input type="checkbox" name="method_releitura"> Releitura</label><label><input type="checkbox" name="method_videoaula"> Videoaula</label><label><input type="checkbox" name="method_explicacao"> Expliquei o conteúdo</label><label><input type="checkbox" name="method_mapa"> Mapa mental</label><label><input type="checkbox" name="method_monitoria"> Monitoria</label><label><input type="checkbox" name="method_outro"> Outro</label></div><div class="check-list"><label><input type="checkbox" name="needsAttention"> Este conteúdo precisa de mais atenção</label></div><div id="follow-up"></div>${input('Observação sobre a monitoria','monitoringNotes','','text','maxlength="500"')}${area('Descreva como você revisou','reviewDescription','')}${area('Outras observações','notes','')}`,async(f,d)=>{if(+d.correct>+d.total)throw new Error('Os acertos não podem superar o total.');const methods=['questoes','correcao','resumo','flashcards','releitura','videoaula','explicacao','mapa','monitoria','outro'].filter(k=>f.elements['method_'+k]?.checked);await save('feedback',{...d,sessionId:sessionId||'',contentId:contentId||'',actualMin:+d.actualMin,total:+d.total,correct:+d.correct,perceivedDifficulty:+d.perceivedDifficulty,monitoring:d.monitoring==='yes',needsAttention:!!f.elements.needsAttention?.checked,methods});});}
const optionNames={exception:'Foi pontual',recurring:'Vai se repetir',duration:'A tarefa demorou mais',instruction:'Não entendi a orientação',current:'Não consegui aplicar o conteúdo',prerequisite:'Faltou um conhecimento anterior',phone:'Celular / notificações',environment:'Ambiente / pessoas',long:'Bloco longo',no:'Não',yes:'Sim',review:'Rever a tarefa',support:'Pedir apoio'};
function followup(){const f=$('#modal-form');if(!f?.elements.reason)return;let reason=f.elements.reason.value;const rule=S.advice[reason];$('#follow-up').innerHTML=rule?select(esc(rule[0]),'detail','',Object.keys(rule[1]).map(k=>[k,optionNames[k]||k]))+'<div class="notice" id="advice-text"></div>':'';if(rule)$('#advice-text').textContent=Object.values(rule[1])[0];}
function accountForm(id){const a=accounts.find(a=>a.id===id)||{username:'',name:'',active:1};modalForm(id?'Editar acesso':'Criar conta',`<div class="form-grid">${input('Nome','name',a.name,'text','required maxlength="150"')}${input('Login','username',a.username,'text','required minlength="3" maxlength="40" autocapitalize="none" '+(id?'readonly':''))}${a.username==='arcmb'?'<p>O Master proprietário altera sua própria senha em “Minha senha”.</p>':input(id?'Nova senha provisória (deixe vazia para manter)':'Senha provisória','password','','password',`minlength="8" maxlength="128" autocomplete="new-password" ${id?'':'required'}`)}${a.username==='arcmb'?'<p>Perfil: Master permanente.</p>':select('Perfil de acesso','role',a.role==='user'?'aluno':a.role||'aluno',[['aluno','Aluno — somente a própria conta'],['coordenador','Coordenador — consulta e edição dos alunos'],['especial','Especial — titular e Master'],['master','Master — acesso completo']])}${check('Conta ativa','active',!!a.active)}</div><p class="micro">Ao definir uma senha, os acessos anteriores serão encerrados e o usuário deverá trocá-la no próximo login. A senha não será exibida depois de salva.</p>`,async(f,d)=>{await api('/api/accounts',{...d,id,active:f.elements.active.checked});await refreshAccounts();await load();toast('Conta atualizada.');});}
async function refreshAccounts(){if(!manages())return;accounts=(await api('/api/accounts')).accounts;$('#account-wrap').hidden=false;$('#account-select').innerHTML=accounts.map(x=>`<option value="${x.id}" ${target===x.id?'selected':''}>${esc(x.name)}</option>`).join('');}
function download(filename,text,mime='application/json'){const url=URL.createObjectURL(new Blob([text],{type:mime+';charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function csv(filename,rows){const cell=v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download(filename,'\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv');}
function csvAnswers(){const rows=[['Perfil','Categoria','Campo','Resposta'],...Object.entries(P.answers).map(([k,v])=>[P.name,'Diagnóstico',k,Array.isArray(v)?v.join(', '):v]),...P.availability.map(x=>[P.name,'Disponibilidade',days[x.day],x.status+' '+x.ranges.map(r=>r.start+'–'+r.end).join('; ')]),...P.fixed.map(x=>[P.name,'Compromisso',x.title,`${x.start}–${x.end}; ${x.recurrence}; referência ${x.anchor}; dias ${x.days.map(d=>days[d]).join(', ')}`]),...Object.entries(P.settings).map(([k,v])=>[P.name,'Configuração',k,Array.isArray(v)?v.join(', '):v])];csv('Respostas_rotina_'+P.name+'.csv',rows);}
function exportICS(){const text=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=(d,m)=>d.replace(/-/g,'')+'T'+hm(m).replace(':','')+'00';const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Meu Cronograma//PT-BR','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const s of [...calendar,...P.sessions.filter(x=>x.date>=week&&x.date<=add(week,6)&&x.status!=='missed')]){const utc=(d,m)=>{let t=new Date(d+'T00:00:00-03:00');t.setMinutes(t.getMinutes()+m);return t.toISOString().replace(/[-:]/g,'').slice(0,15)+'Z';};rows.push('BEGIN:VEVENT','UID:'+s.id+'-'+s.date+'@meucronograma','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').slice(0,15)+'Z','DTSTART:'+utc(s.date,s.start),'DTEND:'+utc(s.date,s.end),'SUMMARY:'+text(s.title),'DESCRIPTION:'+text(s.reason||'Compromisso cadastrado.'),'END:VEVENT');}rows.push('END:VCALENDAR');download('Semana_'+week+'.ics',rows.join('\r\n')+'\r\n','text/calendar');}
const acts={
 'go-calendar':()=>{view='calendar';render();},'new-subject':()=>subjectForm(),'edit-subject':e=>subjectForm(e.dataset.id),'new-content':contentForm,'new-fixed':()=>fixedForm(),'edit-fixed':e=>fixedForm(e.dataset.id),'new-account':()=>accountForm(),'edit-account':e=>accountForm(e.dataset.id),
 'new-exception':()=>modalForm('Bloqueio pontual',`${input('Motivo / atividade','title','','text','required maxlength="250"')}<div class="form-grid">${input('Data','date',S.serverDate,'date','required')}${input('Início','start','14:00','time','required')}${input('Fim','end','15:00','time','required')}</div>`,async(f,d)=>save('exception',d)),
 'restudy':e=>{const c=P.contents.find(x=>x.id===e.dataset.id);modalForm('Novo encontro: '+c.title,`<div class="form-grid">${input('Data do estudo','date',S.serverDate,'date',`required max="${S.serverDate}"`)}${input('Início','time','09:00','time','required')}${input('Tempo utilizado (min)','minutes',c.studyMinutes||40,'number','min="0" max="720" required')}</div><p>A execução é acrescentada ao histórico e inicia um novo ciclo de revisão.</p>`,async(f,d)=>save('restudy',{...d,id:c.id,minutes:+d.minutes}));},
 'edit-review':e=>{const c=P.contents.find(x=>x.id===e.dataset.id);modalForm('Revisão: '+c.title,`${input('Próxima data-alvo','nextDue',c.nextDue,'date')}${check('Pausar revisões deste conteúdo','paused',c.paused)}<p class="micro">Blocos futuros de revisão não fixados serão retirados para novo encaixe. Blocos fixados precisam ser revisados manualmente.</p>`,async(f,d)=>save('review',{id:c.id,nextDue:d.nextDue,paused:f.elements.paused.checked}));},
 'delete':async e=>{if(!confirm('Excluir este registro? O histórico vinculado, quando houver, será protegido.'))return;await save('delete',{collection:e.dataset.collection,id:e.dataset.id});},
 'generate':async()=>{if(!safeLeave())return;await save('generate',{week});},'calendar-mode':()=>{mode=mode==='list'?'grid':'list';render();},'print':()=>print(),
 'feedback':e=>feedbackForm(e.dataset.id),'feedback-content':e=>feedbackForm(null,e.dataset.id),
 'edit-session':e=>{const s=P.sessions.find(x=>x.id===e.dataset.id);modalForm('Ajustar horário',`<p>${esc(s.title)}</p><div class="form-grid">${input('Data','date',s.date,'date','required')}${input('Início','start',hm(s.start),'time','required')}${input('Fim','end',hm(s.end),'time','required')}${check('Fixar este bloco no recálculo','locked',!!s.locked)}</div>`,async(f,d)=>save('session',{...d,id:s.id,locked:f.elements.locked.checked}));},
 'session-detail':e=>{const s=P.sessions.find(x=>x.id===e.dataset.id);modal(s.title,sessionItem(s),null);},
 'open-account':async e=>{if(!safeLeave())return;target=e.dataset.id;view='home';await refreshAccounts();await load();},
 'export-json':async()=>{let b=await api('/api/backup?user='+encodeURIComponent(target));download('Meu_Cronograma_'+P.name+'.json',JSON.stringify(b,null,2));toast('Backup solicitado. Confira se o arquivo foi guardado.');},
 'export-all':async()=>{let b=await api('/api/backup?all=1');download('Meu_Cronograma_todas_contas.json',JSON.stringify(b,null,2));},
 'export-answers':csvAnswers,'export-checks':()=>csv('Verificacoes_'+P.name+'.csv',[['Data','Disciplina','Conteúdo','Resultado','Minutos','Questões','Acertos','Ajuda','Confiança','Motivo','Detalhe','Orientação','Observação'],...P.feedback.map(f=>[f.date,sub(f.subjectId),P.contents.find(c=>c.id===f.contentId)?.title||'',names[f.status],f.actualMin,f.total,f.correct,f.help,f.confidence,f.reason,f.detail,f.advice||f.message,f.notes])]),
 'export-week':()=>csv('Semana_'+week+'.csv',[['Data','Início','Fim','Ação','Tipo','Resultado'],...[...calendar,...P.sessions.filter(x=>x.date>=week&&x.date<=add(week,6))].sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start).map(s=>[s.date,hm(s.start),hm(s.end),s.title,names[s.kind],names[s.status]])]),'export-ics':exportICS,
 'import':()=>$('#import-file').click(),
 'audit':async()=>{let d=await api('/api/audit');$('#audit-results').innerHTML=items(d.events.map(x=>`<div class="item"><div><strong>${esc(x.actor)} → ${esc(x.target)}</strong><p>${esc(x.kind)}</p><small>${esc(new Date(x.at).toLocaleString('pt-BR'))}</small></div></div>`));}
};
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){if(!safeLeave())return;dirty=false;view=nav.dataset.view;$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);return;}const b=e.target.closest('[data-act]');if(!b)return;const action=acts[b.dataset.act];if(!action)return;e.preventDefault();b.disabled=true;try{await action(b);}catch(err){toast(err.message,true);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['modal-form','diagnosis-form','routine-form','password-form'].includes(f.id))return;e.preventDefault();if(saving||!f.reportValidity())return;const b=f.querySelector('button[type=submit]');b.disabled=true;let d=fd(f);try{
 if(f.id==='modal-form'){await modalHandler(f,d);closeModal(true);}
 if(f.id==='diagnosis-form'){d.obstacles=Object.keys(d).filter(k=>k.startsWith('obstacle:')).map(k=>k.slice(9));await save('diagnosis',d);}
 if(f.id==='routine-form'){const settings={...P.settings,...Object.fromEntries(['sleepStart','sleepEnd','preferred'].map(k=>[k,d[k]])),sameDay:f.elements.sameDay.checked,intervals:d.intervals.split(',').map(x=>Number(x.trim()))};for(const k of ['sessionMin','sessionMax','breakMin','dailyMax','weeklyGoal','reservePct','reviewMin'])settings[k]=Number(d[k]);const availability=days.map((_,i)=>({day:i,status:d['status'+i],ranges:d['range'+i].trim()?d['range'+i].split(';').map(x=>{let match=x.trim().match(/^(\d{2}:\d{2})\s*-\s*(\d{2}:\d{2})$/);if(!match)throw new Error('Use faixas como 14:00-16:00; 19:00-21:00.');return {start:match[1],end:match[2]};}):[]}));await save('routine',{settings,availability});}
 if(f.id==='password-form'){await api('/api/password',d);dirty=false;ME.must_change=0;view='home';await refreshAccounts();await load();toast('Senha alterada.');}
 }catch(err){toast(err.message,true);if(f.id==='modal-form'&&$('#modal-error'))$('#modal-error').textContent=err.message;}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.closest('form')){dirty=true;status('Alterações pendentes · clique em Salvar',true);}if(e.target.id==='content-search'){let q=e.target.value.toLocaleLowerCase();$('#content-list').innerHTML=contentRows(P.contents.filter(c=>(c.title+' '+c.topic+' '+sub(c.subjectId)).toLocaleLowerCase().includes(q)));}});
document.addEventListener('change',async e=>{try{
 if(e.target.closest('form'))dirty=true;
 if(e.target.name==='reason')followup();
 if(e.target.name==='detail'){const f=$('#modal-form');$('#advice-text').textContent=S.advice[f.elements.reason.value][1][e.target.value];}
 if(e.target.name==='status'&&$('#modal-form')?.elements.actualMin&&e.target.value==='missed'){for(const k of ['actualMin','total','correct'])$('#modal-form').elements[k].value=0;}
 if(e.target.id==='week-input'){week=weekOf(e.target.value);await loadCalendar();render();}
 if(e.target.id==='account-select'){if(!safeLeave()){e.target.value=target;return;}target=e.target.value;await load();}
 if(e.target.id==='import-file'){const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5000000)throw new Error('Limite de 5 MB.');let data=JSON.parse(await file.text());if(data.app!=='ritmo-local'||data.version!==1||!Array.isArray(data.profiles)||!data.profiles.length)throw new Error('Backup não reconhecido.');modalForm('Importar planejamento',`${select('Perfil do arquivo','profileIndex','0',data.profiles.map((p,i)=>[i,p.name]))}<div class="notice danger">O planejamento de ${esc(P.name)} será substituído. Login, senha e permissões não serão alterados.</div>${check('Já exportei um backup e confirmo a substituição','confirm')}`,async(f,d)=>{if(!f.elements.confirm.checked)throw new Error('Confirme a substituição.');await save('import',{profile:data.profiles[Number(d.profileIndex)]});},'Importar e substituir');}
 }catch(err){toast(err.message,true);}});
